def createparser():
    """Create and return an ArgumentParser for the pysemver CLI."""
    import argparse
    parser = argparse.ArgumentParser(prog='pysemver', description='Semantic Versioning utilities')
    subparsers = parser.add_subparsers(dest='command')
    # bump command
    bump_parser = subparsers.add_parser('bump', help='Bump a component of a version')
    bump_parser.add_argument('version', help='original version string')
    bump_parser.add_argument('component', choices=['major', 'minor', 'patch', 'prerelease', 'build'], help='component to bump')
    bump_parser.add_argument('--token', default=None, help='token for prerelease or build bump')
    # parse command
    parse_parser = subparsers.add_parser('parse', help='Parse a version string')
    parse_parser.add_argument('version', help='version string to parse')
    # compare command
    compare_parser = subparsers.add_parser('compare', help='Compare two version strings')
    compare_parser.add_argument('v1', help='first version')
    compare_parser.add_argument('v2', help='second version')
    return parser


def process(args):
    """Process parsed arguments from createparser."""
    if args.command == 'bump':
        if args.component == 'major':
            return bump_major(args.version)
        if args.component == 'minor':
            return bump_minor(args.version)
        if args.component == 'patch':
            return bump_patch(args.version)
        if args.component == 'prerelease':
            return bump_prerelease(args.version, args.token or 'rc')
        if args.component == 'build':
            return bump_build(args.version, args.token or 'build')
    if args.command == 'parse':
        return parse(args.version)
    if args.command == 'compare':
        return compare(args.v1, args.v2)
    raise ValueError('Unknown command')


def main(argv=None):
    """Entry point for the pysemver CLI."""
    parser = createparser()
    args = parser.parse_args(argv)
    result = process(args)
    if result is not None:
        print(result)
